"use client";

import type { ComponentProps, ReactNode } from "react";
import { DownloadIcon } from "lucide-react";
import { cn } from "@/registry/dimah-s3-ui/lib/utils";
import { formatFileSize } from "@dimah-s3/core";
import type { FetchDownloadHooks } from "@dimah-s3/react";
import type { S3Api } from "@dimah-s3/core";
import { useTranslations } from "@fuma-translate/react";
import { useFetchDownload } from "@dimah-s3/react";
import { resolveStatusSlot, type StatusSlot } from "@/registry/dimah-s3-ui/lib/status-slot";
import { Button } from "@/registry/dimah-s3-ui/components/ui/button";
import { StatusAttachment } from "@/registry/dimah-s3-ui/components/dimah-s3/status-attachment";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/registry/dimah-s3-ui/components/ui/tooltip";
import { useDownloadToast } from "@/registry/dimah-s3-ui/hooks/use-download-toast";

/** Props for {@link ProgressDownloadButton}. */
export type ProgressDownloadButtonProps = FetchDownloadHooks & {
  /** S3Api. Optional when an `<S3Provider>` is present in the tree. */
  api?: S3Api;
  /** S3 object key to download. */
  objectKey: string;
  /** Download filename for Content-Disposition. */
  fileName?: string;
  /** Total file size in bytes (used for progress display). */
  fileSize?: number;
  /** Target bucket (overrides server default). */
  bucket?: string;
  /** Button label. */
  label?: string;
  /** Custom button content. Replaces default icon + label / progress text. */
  children?: ReactNode;
  className?: string;
  fillClassName?: string;
  disabled?: boolean;
  tooltipText?: string;
  /** Tooltip while downloading (click cancels). @default "Cancel download" */
  cancelTooltipText?: string;
  /** Show toasts during download. @default true */
  toast?: boolean;
  /**
   * Inline status control.
   * - `true` (default): render below the button
   * - `false`: hide status
   * - `(node) => ReactNode`: wrap or relocate the status node
   */
  status?: StatusSlot;
  /** Button variant. @default "outline" */
  variant?: ComponentProps<typeof Button>["variant"];
  /** Button size. @default "default" */
  size?: ComponentProps<typeof Button>["size"];
  /** Extra classes on the trigger button element. */
  buttonClassName?: string;
};

export function ProgressDownloadButton({
  api,
  objectKey,
  fileName,
  fileSize,
  bucket,
  label,
  children,
  className,
  fillClassName,
  disabled,
  tooltipText,
  cancelTooltipText,
  toast: enableToast = true,
  status: statusSlot = true,
  variant = "outline",
  size = "default",
  buttonClassName,
  beforeDownload,
  onDownloadStart,
  onProgress,
  onSuccess,
  onError,
  onCancel,
}: ProgressDownloadButtonProps) {
  const t = useTranslations();
  const toastHandlers = useDownloadToast({
    enabled: enableToast,
    objectKey,
    fileName,
    fileSize,
  });

  const dl = useFetchDownload({
    api,
    bucket,
    beforeDownload,
    onDownloadStart,
    onProgress,
    onSuccess: (key, actualFileName) => {
      toastHandlers.onSuccess(key, actualFileName);
      onSuccess?.(key, actualFileName);
    },
    onError: (key, error, phase) => {
      toastHandlers.onErrorWithPhase(key, error, phase);
      onError?.(key, error, phase);
    },
    onCancel: (key) => {
      toastHandlers.onCancel(key);
      onCancel?.(key);
    },
  });

  const isDownloading = dl.phase === "downloading" || dl.phase === "presigning";

  const handleClick = () => {
    if (isDownloading) {
      dl.cancel();
      return;
    }
    dl.download(objectKey, fileName);
  };

  const computedPercentFromFileSize =
    fileSize && fileSize > 0
      ? Math.min(100, Math.round((dl.progress.loaded / fileSize) * 100))
      : null;

  const fillPercent =
    dl.phase === "presigning"
      ? 12
      : dl.progress.total > 0
        ? dl.progress.percent
        : computedPercentFromFileSize;

  const isIndeterminateFill =
    isDownloading && fillPercent == null && dl.phase === "downloading";

  const buttonContent = children ?? (
    <>
      {!isDownloading && <DownloadIcon data-icon="inline-start" />}
      {isDownloading
        ? formatFileSize(dl.progress.loaded)
        : (label ?? t("Download", { note: "button" }))}
    </>
  );

  const statusNode =
    dl.phase === "error" ? (
      <StatusAttachment
        state="error"
        title={t("Download failed", { note: "status" })}
        description={dl.error ?? undefined}
      />
    ) : null;

  return (
    <div className={cn("inline-flex flex-col items-center gap-2", className)}>
      <Tooltip>
        <TooltipTrigger
          render={
            <Button
              variant={variant}
              size={size}
              disabled={disabled}
              className={cn(
                "relative min-w-24 overflow-hidden",
                buttonClassName,
              )}
              onClick={handleClick}
            />
          }
        >
          {isDownloading && (
            <span
              className={cn(
                "absolute inset-y-0 start-0 bg-primary/15",
                fillPercent != null
                  ? "transition-[width] duration-200"
                  : "w-full animate-pulse",
                fillClassName,
              )}
              style={
                fillPercent != null ? { width: `${fillPercent}%` } : undefined
              }
              aria-hidden={isIndeterminateFill}
            />
          )}
          <span className="relative z-10 flex w-full items-center justify-center gap-1">
            {buttonContent}
          </span>
        </TooltipTrigger>
        <TooltipContent>
          {isDownloading
            ? (cancelTooltipText ?? t("Cancel download", { note: "tooltip" }))
            : (tooltipText ?? t("Download file", { note: "tooltip" }))}
        </TooltipContent>
      </Tooltip>

      {resolveStatusSlot(statusSlot, statusNode)}
    </div>
  );
}

"use client";

import { formatFileSize, truncateFileName } from "@dimah-s3/core";
import { useTranslations } from "@fuma-translate/react";
import { useFormatDimahError } from "@dimah-s3/react";

import { toast } from "@/components/ui/toast";

export type DownloadToastOptions = {
  enabled?: boolean;
  objectKey: string;
  fileName?: string;
  fileSize?: number;
};

export function useDownloadToast({
  enabled = true,
  objectKey,
  fileName,
  fileSize,
}: DownloadToastOptions) {
  const t = useTranslations();
  const formatDimahError = useFormatDimahError();
  const displayName = fileName ?? objectKey.split("/").pop() ?? objectKey;

  const errorNode = (error: unknown) => (
    <span dir="auto" className="block [overflow-wrap:anywhere]">
      {formatDimahError(error)}
    </span>
  );

  const onInitiated = () => {
    if (enabled) {
      toast.add({
        type: "success",
        title: t("Download started", { note: "toast" }),
      });
    }
  };

  const onSuccess = (_key: string, actualFileName: string) => {
    if (!enabled) return;
    toast.close(`dl-${objectKey}`);
    toast.add({
      type: "success",
      title: t("Download complete", { note: "toast" }),
      description: (
        <span className="block">
          <bdi>{truncateFileName(actualFileName)}</bdi>
          {fileSize != null ? (
            <>
              {" "}
              ·{" "}
              <span
                dir="ltr"
                className="inline-block whitespace-nowrap tabular-nums"
              >
                {formatFileSize(fileSize)}
              </span>
            </>
          ) : null}
        </span>
      ),
    });
  };

  const onError = (_key: string, error: unknown) => {
    if (!enabled) return;
    toast.close(`dl-${objectKey}`);
    toast.add({
      type: "error",
      title: t("Download failed", { note: "toast" }),
      description: errorNode(error),
    });
  };

  const onErrorWithPhase = (_key: string, error: unknown, _phase: string) => {
    if (!enabled) return;
    toast.close(`dl-${objectKey}`);
    toast.add({
      type: "error",
      title: t("Download failed", { note: "toast" }),
      description: errorNode(error),
    });
  };

  const onCancel = (_key: string) => {
    if (!enabled) return;
    toast.close(`dl-${objectKey}`);
    toast.add({
      type: "info",
      title: t("Download cancelled", { note: "toast" }),
      description: <span dir="auto">{truncateFileName(displayName)}</span>,
    });
  };

  return { onInitiated, onSuccess, onError, onErrorWithPhase, onCancel };
}

"use client";

import type { ReactNode } from "react";
import {
  AlertCircleIcon,
  CheckCircleIcon,
  LoaderCircleIcon,
} from "lucide-react";
import { cn } from "@/registry/dimah-s3-ui/lib/utils";
import {
  Attachment,
  AttachmentActions,
  AttachmentContent,
  AttachmentDescription,
  AttachmentMedia,
  AttachmentTitle,
} from "@/registry/dimah-s3-ui/components/ui/attachment";

export type StatusAttachmentState =
  "idle" | "uploading" | "processing" | "error" | "done";

export type StatusAttachmentProps = {
  state: StatusAttachmentState;
  title?: ReactNode;
  description?: ReactNode;
  media?: ReactNode;
  actions?: ReactNode;
  className?: string;
};

/**
 * Minimal Attachment shell for operation feedback (upload/download/delete).
 * Relies on Attachment `data-state` styles for error/done chrome.
 */
export function StatusAttachment({
  state,
  title,
  description,
  media,
  actions,
  className,
}: StatusAttachmentProps) {
  const defaultMedia =
    state === "error" ? (
      <AlertCircleIcon />
    ) : state === "done" ? (
      <CheckCircleIcon />
    ) : state === "processing" || state === "uploading" ? (
      <LoaderCircleIcon className="animate-spin" data-slot="spinner" />
    ) : null;

  return (
    <Attachment
      state={state}
      size="sm"
      orientation="horizontal"
      className={cn("w-full max-w-full", className)}
    >
      <AttachmentMedia>{media ?? defaultMedia}</AttachmentMedia>
      <AttachmentContent>
        {title != null ? (
          <AttachmentTitle className="max-w-[30ch]">{title}</AttachmentTitle>
        ) : null}
        {description != null ? (
          <AttachmentDescription
            className={
              state === "error"
                ? "overflow-visible whitespace-normal [overflow-wrap:anywhere]"
                : undefined
            }
          >
            {description}
          </AttachmentDescription>
        ) : null}
      </AttachmentContent>
      {actions ? <AttachmentActions>{actions}</AttachmentActions> : null}
    </Attachment>
  );
}

import type { ReactNode } from "react";

/**
 * Controls inline status rendering for wired UI components.
 *
 * - `true` (default): render the status node in the default slot
 * - `false`: hide status
 * - `(node) => ReactNode`: wrap or relocate the status node
 */
export type StatusSlot = boolean | ((node: ReactNode) => ReactNode);

/** Resolve a {@link StatusSlot} against a built status node. */
export function resolveStatusSlot(
  slot: StatusSlot = true,
  node: ReactNode,
): ReactNode {
  if (slot === false) return null;
  if (typeof slot === "function") return slot(node);
  return node;
}
